import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DXYAzton.js";import"./chunks/assets.CEP5Mpur.js";var i=JSON.parse(`{"title":"Syllabus | CSCI 498 Senior Project Construction","description":"","frontmatter":{},"headers":[],"relativePath":"syllabi/Syllabus_498.md","filePath":"syllabi/Syllabus_498.md","lastUpdated":1785290425000}`),a={name:`syllabi/Syllabus_498.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<figure><img src="/CSCI-Senior-Projects/assets/csu_logo.DSaFiBcI.svg" alt="CSU Logo"></figure><h1 id="syllabus-csci-498-senior-project-construction" tabindex="-1">Syllabus | CSCI 498 Senior Project Construction <a class="header-anchor" href="#syllabus-csci-498-senior-project-construction" aria-label="Permalink to “Syllabus | CSCI 498 Senior Project Construction”">​</a></h1><h2 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to “General Information”">​</a></h2><p>Department: Computer Science<br> Course Name: Senior Project Construction<br> Course Number: CSCI 498<br> Credit Hours: 1<br> Approved Major Credit: BS in Computer Science, BS in Cybersecurity, BA in Computer and Information Sciences, BT in Computer Science, and BT in Cybersecurity<br> LAC Requirement: None<br> Prerequisites: CSCI 497</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to “Course Description”">​</a></h2><p><em>Senior Project Construction</em> is the second course in a three-part project-based capstone series for the Computer Science degree program. The student will complete the construction of a significant project in the field of Computer Science as well as submit a test plan for this project. Upon completion of CSCI 498, the student may progress to CSCI 499 Senior Project Defense.</p><h2 id="course-materials" tabindex="-1">Course Materials <a class="header-anchor" href="#course-materials" aria-label="Permalink to “Course Materials”">​</a></h2><p>Additional Materials for Learning</p><ol><li>Computer with basic audio/video output equipment</li><li>Internet access</li><li>A <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> Account</li></ol><h2 id="abet-student-learning-outcomes" tabindex="-1">ABET Student Learning Outcomes <a class="header-anchor" href="#abet-student-learning-outcomes" aria-label="Permalink to “ABET Student Learning Outcomes”">​</a></h2><p>The following student outcomes are to be supported by this coursework:</p><ol start="2"><li><p>An ability to design, implement, and evaluate a computer-based system, process, component, or program to meet desired needs.</p></li><li><p>An ability to communicate effectively with a range of audiences.</p></li><li><p>Recognize professional responsibilities and make informed judgments in computing practice based on legal and ethical principles.</p></li></ol><h2 id="learning-objectives" tabindex="-1">Learning Objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to “Learning Objectives”">​</a></h2><p>At the end of this course, the student is expected to have completed a majority of the construction of his/her project and to have submitted a test plan to his/her advisor based on the software requirements specification from CSCI 497. The project will likely take the form of a large software program in the language agreed upon by the advisor. The advisor will assist the student when necessary and approve the progress of the student on to Senior Defense.</p><h2 id="weekly-objectives-and-tasks" tabindex="-1">Weekly Objectives and Tasks <a class="header-anchor" href="#weekly-objectives-and-tasks" aria-label="Permalink to “Weekly Objectives and Tasks”">​</a></h2><p>The student will complete work according to the schedule developed in CSCI 497. Schedule changes may be applied if agreed upon by both the advisor and the student. The student is also responsible for giving weekly progress reports to the advisor and attending all senior project meetings as announced by the CSCI faculty.</p><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to “Grading”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Objective</th><th>Grade Weight</th></tr></thead><tbody><tr><td style="text-align:right;">Test Plan</td><td>50%</td></tr><tr><td style="text-align:right;">Significant Progress Made in Project</td><td>50%</td></tr></tbody></table><h2 id="attendance" tabindex="-1">Attendance <a class="header-anchor" href="#attendance" aria-label="Permalink to “Attendance”">​</a></h2><p>The student is expected to schedule a meeting with the project advisor within the first full week of the class. During this initial meeting, the attendance policies will be discussed and meeting times will be scheduled between the student and advisor.</p><h2 id="course-department-and-university-policies" tabindex="-1">Course, Department, and University Policies <a class="header-anchor" href="#course-department-and-university-policies" aria-label="Permalink to “Course, Department, and University Policies”">​</a></h2><h3 id="academic-integrity-and-the-honor-code" tabindex="-1">Academic Integrity and the Honor Code <a class="header-anchor" href="#academic-integrity-and-the-honor-code" aria-label="Permalink to “Academic Integrity and the Honor Code”">​</a></h3><p>All students are expected to adhere to <a href="https://www.charlestonsouthern.edu/wp-content/uploads/Policy-R-58-updated-November-2025.pdf" target="_blank" rel="noreferrer">Charleston Southern University&#39;s Academic Integrity Policy</a> and the <a href="/CSCI-Senior-Projects/integrity">Computer Science Departmental Guidelines</a>. For example, all work must be original and must not be copied from another student. Failure to follow this guideline will be considered a violation of the code and will be treated accordingly. Students are encouraged to ask their instructor(s) for clarification regarding their academic integrity.</p><h3 id="ai-policy-for-csci-498" tabindex="-1">AI Policy for CSCI 498 <a class="header-anchor" href="#ai-policy-for-csci-498" aria-label="Permalink to “AI Policy for CSCI 498”">​</a></h3><p><strong>Level 2. Permitting or prohibiting AI use on an assignment-by-assignment basis in CSCI 498.</strong></p><p>The use of generative AI is prohibited for all work on your senior project unless expressly granted by your project advisor. Such permission may be rare and highly dependent on the project and deliverables. To comprehend the various concepts presented in the course material takes considerable effort and practice. Accordingly, the use of artificial intelligence (AI) tools is generally prohibited in this course but will be permitted for select deliverables.</p><p>Generative artificial intelligence (AI) tools are prohibited from use in any step in the process of creating the test plan (idea generation, outlining, writing, etc.).</p><p>If AI is used in any capacity for a deliverable, AI requires proper attribution. Given that there is no person to whom the work can be attributed, students should attribute directly quoted text to the creator of the AI tool used (e.g., cite OpenAI when directly quoting ChatGPT). This attribution must be used for both in-text citations and in the reference section.</p><p>When using material generated from an AI model in submitted assignments, transparency is key, and these instances must be properly referenced. Use the APA or IEEE style guide for citation.</p><h4 id="ai-citation-example" tabindex="-1">AI Citation example <a class="header-anchor" href="#ai-citation-example" aria-label="Permalink to “AI Citation example”">​</a></h4><p>Scenario: Your project implementation, a financial investment app, uses ChatGPT agents to simulate stock trades.</p><ol><li><p><strong>Acknowledge the Tool</strong> For example:</p><blockquote><p>This project implementation used OpenAI’s ChatGPT agents to assist with prototyping investment recommendation logic, generating code snippets, and testing potential trading scenarios.</p></blockquote></li><li><p><strong>Document the Scope of Use</strong><br> Be clear about how you used it and where its contributions end. For example:</p><ul><li>Uses ChatGPT agents to simulate stock trades</li><li>Not used to make real financial decisions or give live trading advice.</li></ul></li><li><p>Include a Proper Reference<br> In your project&#39;s references section, add something like:</p><ul><li>APA style<br> OpenAI. (2025). ChatGPT (GPT-5) [Large language model]. <a href="https://chat.openai.com/" target="_blank" rel="noreferrer">https://chat.openai.com/</a></li><li>IEEE style<br> [1] OpenAI, ChatGPT (GPT-5). [Online]. Available: <a href="https://chat.openai.com/" target="_blank" rel="noreferrer">https://chat.openai.com/</a></li></ul></li></ol><h3 id="course-evaluations" tabindex="-1">Course Evaluations <a class="header-anchor" href="#course-evaluations" aria-label="Permalink to “Course Evaluations”">​</a></h3><p>To pursue our mission of <em>Academic Excellence in a Christian Environment</em>, we must receive feedback from students. The student-feedback survey is online and will be available to students in the second half of the semester. Students are strongly encouraged to complete the short evaluation survey, which is anonymous. Your professor will let you know when the survey is available. The survey will be available through your MyCSU account. We greatly value your opinion!</p><h3 id="student-representatives" tabindex="-1">Student Representatives <a class="header-anchor" href="#student-representatives" aria-label="Permalink to “Student Representatives”">​</a></h3><p>These are students who are designated by letter to represent the University in official business (e.g., athletic, music, and similar events). If officially scheduled absences cause these students to miss tests, assignments, or similar academic activities, university policy allows these to be made up without penalty. Student Representatives may opt to either make-up tests <em>before</em> departure or supplant missed tests with the final exam grade. Final exams must always be taken <em>before</em> departure to avoid an Incomplete for the course. Scheduled assignments remain subject to the lateness policy and must be turned in before departure to avoid lateness penalties. Student Representatives are responsible for informing the instructor of official absences and to make all appropriate arrangements.</p><h3 id="internet-etiquette" tabindex="-1">Internet Etiquette <a class="header-anchor" href="#internet-etiquette" aria-label="Permalink to “Internet Etiquette”">​</a></h3><p>Charleston Southern University (CSU) holds students, faculty, and staff to the highest standards of conduct and expects all to demonstrate courteous behaviors and practices in online communications. This policy includes guidelines and recommendations for online communications. Being respectful, thoughtful, meaningful, and ethical are fundamental to good netiquette.</p><p>CSU&#39;s basic netiquette rules are:</p><ul><li>Course communications are for internal use only and considered confidential. Do not forward or quote discussion posts, emails, or other course communications to outside parties.</li><li>Never share personal login usernames, IDs or passwords.</li><li>Do not type in all capital letters. It is perceived online as shouting.</li><li>Use proper capitalization, grammar, spelling, and punctuation conventions for professional communications.</li><li>Avoid texting jargon or abbreviations without explanation. <ul><li>Incorrect: &quot;CSU is a wonderful university.&quot;</li><li>Correct: &quot;Charleston Southern University (CSU) is a wonderful university.&quot;</li></ul></li><li>Be mindful of sending emails. Ensure that content is relevant and pay attention to <em>Reply</em> versus <em>Reply All</em>.</li><li>BucMail is the only email allowed for course communications. Other platforms (Yahoo, Gmail, etc.) are prohibited.</li><li>In video conferencing, mute your microphone when not speaking.</li><li>Differing views are natural and welcome in discussion boards. Be respectful in your comments-even if you disagree or dislike someone&#39;s position on a topic.</li><li>Respect the time and availability of students, faculty, and staff. Emails should be addressed within 24 hours of receipt. Keep in mind that traditional faculty work hours are 8 a.m. - 5 p.m. EST.</li></ul><h2 id="accessibility-services" tabindex="-1">Accessibility Services <a class="header-anchor" href="#accessibility-services" aria-label="Permalink to “Accessibility Services”">​</a></h2><p>Any student who may need accommodations should review the requirements/procedures on the <a href="https://www.charlestonsouthern.edu/academics/student-success/accessibility-services/" target="_blank" rel="noreferrer">Accessibility Services website</a>. Once approved to receive accommodations, the student must contact the instructor.</p><h3 id="title-ix-confidentiality-and-responsible-employee-statement" tabindex="-1">Title IX: Confidentiality and Responsible Employee Statement <a class="header-anchor" href="#title-ix-confidentiality-and-responsible-employee-statement" aria-label="Permalink to “Title IX: Confidentiality and Responsible Employee Statement”">​</a></h3><p>Charleston Southern University is committed to maintaining a safe learning environment for everyone. In accordance with Title IX of the Education Amendments of 1972, the university prohibits any form of sexual harassment, including quid pro quo harassment, hostile environments, sexual assault, dating/domestic violence, and stalking. This policy applies to all students, employees, and visitors.</p><p>Additionally, Title IX prohibits discrimination against students based on pregnancy, childbirth, false pregnancy, termination of pregnancy, or recovery from these conditions. Pregnant or parenting students may receive accommodations to ensure their full participation in educational programs. These adjustments can be arranged through the university’s Title IX Coordinator or their designee.</p><p>Under Charleston Southern University’s Title IX Policy, all faculty members, including teaching assistants, are required to report any disclosures of sex or gender-based discrimination or violence to the Title IX Coordinator. The Title IX Coordinator will provide support and resources while maintaining privacy. If you or someone you know needs assistance, please contact the Title IX Coordinator:</p><p><strong>Summer Cora</strong><br> (843)-863-7374<br><a href="mailto:titleix@csuniv.edu" target="_blank" rel="noreferrer">titleix@csuniv.edu</a><br> Office Location: 2nd floor of the Student Center</p><p>Please visit the <a href="https://www.charlestonsouthern.edu/offices/title-ix/" target="_blank" rel="noreferrer">CSU Title IX webpage</a> here for more information on Title IX procedures, anonymous reporting, or available support.</p><hr><p>See all course, department, and university policies located in Blackboard and the <a href="https://www.charlestonsouthern.edu/current-students/student-resources/" target="_blank" rel="noreferrer">CSU Student Handbook</a>.</p>`,50)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};